from collections import defaultdict, deque

def min_jumps(arr):
    n = len(arr)
    if n == 1:
        return 0

    value_to_indices = defaultdict(list)
    for i, val in enumerate(arr):
        value_to_indices[val].append(i)

    visited = [False] * n
    visited[0] = True
    queue = deque([0])
    steps = 0

    while queue:
        for _ in range(len(queue)):
            i = queue.popleft()
            if i == n - 1:
                return steps

            neighbors = value_to_indices[arr[i]]
            neighbors.append(i + 1)
            if i - 1 >= 0:
                neighbors.append(i - 1)

            for j in neighbors:
                if 0 <= j < n and not visited[j]:
                    visited[j] = True
                    queue.append(j)

            value_to_indices[arr[i]] = []

        steps += 1

    return steps

